/* Trackers, coaching, Ask, settings and admin pages. */
.in-list { display: flex; flex-direction: column; }
.in-item { display: flex; gap: 16px; justify-content: space-between; align-items: flex-start; padding: 16px 0; border-bottom: 1px solid var(--line); }
.in-item-main { min-width: 0; flex: 1; }
.in-item-main h3 { font-size: 16.5px; font-weight: 600; }
.in-item-main h3 a { text-decoration: none; }
.in-item-main h3 a:hover { text-decoration: underline; }
.in-item-meta { margin: 4px 0 0; color: var(--ink-2); font-size: 14px; }
.in-item-side { display: flex; align-items: center; gap: 10px; flex-shrink: 0; }
.in-kw { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 6px; }
.in-count { font-variant-numeric: tabular-nums; font-weight: 600; }
.in-radio { display: flex; flex-direction: column; gap: 8px; }
.in-radio label { display: flex; gap: 10px; align-items: flex-start; padding: 10px 12px; border: 1px solid var(--line); border-radius: 8px; cursor: pointer; }
.in-radio label:has(input:checked) { border-color: var(--teal); background: var(--teal-soft); }
.in-radio input { margin-top: 4px; }
.in-filters { display: flex; gap: 10px; align-items: center; flex-wrap: wrap; margin-bottom: 16px; }
.in-filters select { width: auto; }
.in-seg { display: inline-flex; border: 1px solid var(--line); border-radius: 999px; overflow: hidden; }
.in-seg button { background: var(--panel); border: 0; padding: 6px 14px; color: var(--ink-2); }
.in-seg button + button { border-left: 1px solid var(--line); }
.in-seg button[aria-pressed='true'] { background: var(--teal-soft); color: var(--teal); font-weight: 600; }
.in-note { color: var(--ink-2); font-size: 14px; max-width: 75ch; margin: 0 0 14px; }

/* hits */
.in-chart { display: flex; align-items: flex-end; gap: 3px; height: 72px; padding: 8px 0; border-bottom: 1px solid var(--line); margin-bottom: 18px; }
.in-bar { flex: 1; background: var(--teal); border-radius: 3px 3px 0 0; min-height: 2px; opacity: 0.85; }
.in-bar.zero { background: var(--line); }
.in-hit-group { padding: 14px 0; border-bottom: 1px solid var(--line); }
.in-hit-group h3 { font-size: 16px; font-weight: 600; }
.in-hit-group h3 a { text-decoration: none; }
.in-hit { display: grid; grid-template-columns: 56px 1fr; gap: 8px; margin-top: 8px; font-size: 14.5px; }
.in-hit a { text-decoration: none; }
.in-hit q { color: var(--ink); }

/* tables */
.in-table-wrap { overflow-x: auto; border: 1px solid var(--line); border-radius: var(--radius); background: var(--panel); }
.in-table { width: 100%; border-collapse: collapse; font-size: 14.5px; }
.in-table th, .in-table td { text-align: left; padding: 10px 12px; border-bottom: 1px solid var(--line); white-space: nowrap; vertical-align: middle; }
.in-table th { font-weight: 600; color: var(--ink-2); font-size: 13px; }
.in-table tr:last-child td { border-bottom: 0; }
.in-table td.num, .in-table th.num { text-align: right; font-variant-numeric: tabular-nums; }
.in-table select { width: auto; padding: 4px 8px; }
.in-person { display: flex; align-items: center; gap: 8px; }
.in-dim { color: var(--ink-2); }

/* scorecards */
.in-card { border: 1px solid var(--line); border-radius: var(--radius); background: var(--panel); padding: 18px; margin-bottom: 18px; }
.in-card-head { display: flex; justify-content: space-between; gap: 12px; align-items: baseline; flex-wrap: wrap; margin-bottom: 12px; }
.in-card-head h3 { font-size: 17px; font-weight: 600; }
.in-score { font-size: 28px; font-weight: 700; font-variant-numeric: tabular-nums; }
.in-score small { font-size: 14px; color: var(--ink-2); font-weight: 500; }
.in-crit { display: grid; grid-template-columns: minmax(120px, 220px) 1fr 40px; gap: 10px; align-items: center; margin: 6px 0; font-size: 14px; }
.in-track { height: 8px; background: var(--line); border-radius: 4px; overflow: hidden; }
.in-track i { display: block; height: 100%; background: var(--teal); }
.in-cols { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; margin-top: 14px; }
.in-cols h4 { margin: 0 0 6px; font-size: 14px; }
.in-cols ul { list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 4px; font-size: 14px; }
.in-cols li { display: flex; justify-content: space-between; gap: 10px; }

/* ask */
.in-ask { max-width: 820px; display: flex; flex-direction: column; gap: 16px; }
.in-ask-bar { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
.in-ask-bar select { width: auto; }
.in-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.in-chips button { border: 1px solid var(--line); background: var(--panel); border-radius: 999px; padding: 7px 14px; }
.in-chips button:hover { border-color: var(--teal); }
.in-qa .q { font-weight: 600; margin: 0 0 8px; }
.in-qa .a { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); padding: 14px 16px; white-space: pre-wrap; }
.in-qa .a.err { color: var(--bad); border-color: var(--bad-bg); }
.in-qa .src { margin-top: 10px; font-size: 13px; color: var(--ink-2); }
.in-cite { color: var(--teal); font-weight: 600; text-decoration: none; background: var(--teal-soft); border-radius: 4px; padding: 0 4px; white-space: nowrap; }
.in-cite:hover { text-decoration: underline; }
.in-ask-form { display: flex; gap: 8px; position: sticky; bottom: 12px; background: var(--paper); padding-top: 6px; }
.in-ask-form input { border-radius: 999px !important; padding: 10px 16px !important; }

/* settings & admin */
.in-settings { display: flex; flex-direction: column; gap: 28px; max-width: 760px; }
.in-section { border-top: 1px solid var(--line); padding-top: 20px; }
.in-section:first-child { border-top: 0; padding-top: 0; }
.in-section h2 { font-size: 18px; margin: 0 0 4px; }
.in-section > .muted { margin-bottom: 14px; max-width: 70ch; }
.in-secret { display: flex; gap: 8px; align-items: center; background: var(--paper); border: 1px solid var(--line); border-radius: 8px; padding: 8px 10px; }
.in-secret code { flex: 1; min-width: 0; overflow-x: auto; white-space: nowrap; font-size: 13px; }
.in-warn { background: var(--warn-bg); color: var(--warn); border-radius: 8px; padding: 8px 12px; margin: 0; font-size: 14px; }
.in-code { background: var(--panel); border: 1px solid var(--line); border-radius: 8px; padding: 12px 14px; overflow-x: auto; font-size: 13px; margin: 0; }
.in-checks { display: flex; gap: 16px; flex-wrap: wrap; }
.in-checks label { display: flex; gap: 6px; align-items: center; }
.in-admin { display: grid; grid-template-columns: 200px minmax(0, 1fr); gap: 32px; align-items: start; }
.in-subnav { display: flex; flex-direction: column; gap: 2px; position: sticky; top: 80px; }
.in-subnav a { padding: 7px 10px; border-radius: 8px; text-decoration: none; color: var(--ink-2); }
.in-subnav a:hover { background: var(--panel); color: var(--ink); }
.in-subnav a.on { background: var(--teal-soft); color: var(--teal); font-weight: 600; }
.in-admin-body h2.in-title { font-size: 20px; margin: 0 0 4px; }
.in-admin-body > .muted { margin-bottom: 16px; max-width: 70ch; }
.in-team { border: 1px solid var(--line); border-radius: var(--radius); background: var(--panel); padding: 14px 16px; margin-bottom: 14px; }
.in-team-head { display: flex; justify-content: space-between; align-items: center; gap: 10px; margin-bottom: 8px; }
.in-team-head h3 { font-size: 16px; font-weight: 600; }
.in-members { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 6px; }
.in-members li { display: flex; align-items: center; gap: 10px; justify-content: space-between; flex-wrap: wrap; }
.in-members label { display: flex; gap: 6px; align-items: center; font-size: 14px; color: var(--ink-2); }
.in-add-member { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; margin-top: 10px; }
.in-add-member select { width: auto; max-width: 220px; }
.in-crit-row { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 2fr) 34px; gap: 8px; align-items: start; }
.in-terms { display: flex; flex-wrap: wrap; gap: 8px; margin: 12px 0; }
.in-term { display: inline-flex; align-items: center; gap: 4px; border: 1px solid var(--line); background: var(--panel); border-radius: 999px; padding: 3px 4px 3px 12px; font-size: 14px; }
.in-term.bad { border-color: var(--bad); color: var(--bad); }
.in-term button { background: none; border: 0; width: 24px; height: 24px; border-radius: 50%; color: var(--ink-2); display: grid; place-items: center; }
.in-term button:hover { background: var(--teal-soft); }
.in-builtin { font-size: 14px; }
.in-builtin p { margin: 2px 0 0; color: var(--ink-2); }

@media (max-width: 900px) {
  .in-admin { grid-template-columns: minmax(0, 1fr); gap: 16px; }
  .in-subnav { position: static; flex-direction: row; overflow-x: auto; }
  .in-subnav a { white-space: nowrap; }
  .in-cols { grid-template-columns: 1fr; }
  .in-item { flex-direction: column; gap: 10px; }
  .in-crit { grid-template-columns: minmax(0, 1fr) 80px 36px; }
  .in-crit-row { grid-template-columns: minmax(0, 1fr) 34px; }
  .in-crit-row > :nth-child(2) { grid-column: 1; }
}

// Trackers, coaching and account-wide Ask.
import React, { useEffect, useMemo, useRef, useState } from 'react'
import { del, post, patch, qs, useApi } from '../api.js'
import {
  Avatar, Empty, ErrorNote, Field, Loading, Menu, Modal, PageHead, Spinner, Tabs,
  fmtClock, fmtDay, parseHash, useAction, useApp,
} from '../ui.jsx'
import './insights.css'

function Seg({ value, options, onChange, label }) {
  return (
    <span className="in-seg" role="group" aria-label={label}>
      {options.map(([v, text]) => (
        <button key={v} type="button" aria-pressed={value === v} onClick={() => onChange(v)}>{text}</button>
      ))}
    </span>
  )
}

/* ---------- trackers ---------- */
function TrackerModal({ tracker, onClose, onSaved }) {
  const { toast } = useApp()
  const [f, setF] = useState({
    name: tracker?.name || '',
    kind: tracker?.kind || 'keyword',
    keywords: (tracker?.terms?.keywords || []).join(', '),
    description: tracker?.terms?.description || '',
  })
  const [error, setError] = useState(null)
  const [busy, setBusy] = useState(false)
  const submit = async (e) => {
    e.preventDefault()
    setBusy(true); setError(null)
    const body = { name: f.name, kind: f.kind, keywords: f.keywords.split(',').map((k) => k.trim()).filter(Boolean), description: f.description }
    try {
      if (tracker) await patch(`/trackers/${tracker.id}`, body)
      else await post('/trackers', body)
      toast(tracker ? 'Tracker saved. Rescanning past meetings.' : 'Tracker created. Scanning past meetings.')
      onSaved()
      onClose()
    } catch (err) {
      setError(err.message)
    } finally {
      setBusy(false)
    }
  }
  return (
    <Modal title={tracker ? 'Edit tracker' : 'New tracker'} onClose={onClose} footer={
      <>
        <button className="secondary" type="button" onClick={onClose}>Cancel</button>
        <button className="primary" form="tracker-form" disabled={busy}>{busy ? 'Saving' : tracker ? 'Save tracker' : 'Create tracker'}</button>
      </>
    }>
      <form id="tracker-form" className="stack-form" onSubmit={submit}>
        <Field label="Name"><input value={f.name} onChange={(e) => setF({ ...f, name: e.target.value })} placeholder="Competitor mentions" required /></Field>
        <div className="in-radio" role="radiogroup" aria-label="How to find moments">
          <label>
            <input type="radio" name="kind" checked={f.kind === 'keyword'} onChange={() => setF({ ...f, kind: 'keyword' })} />
            <span><b>Keywords</b><br /><span className="muted small">Finds the exact words you list.</span></span>
          </label>
          <label>
            <input type="radio" name="kind" checked={f.kind === 'ai'} onChange={() => setF({ ...f, kind: 'ai' })} />
            <span><b>AI</b><br /><span className="muted small">Finds moments by meaning, even when people use different words.</span></span>
          </label>
        </div>
        {f.kind === 'keyword' ? (
          <Field label="Keywords" hint="Separate with commas. Up to 25.">
            <input value={f.keywords} onChange={(e) => setF({ ...f, keywords: e.target.value })} placeholder="Gong, Otter, Fireflies" />
          </Field>
        ) : (
          <Field label="Moments to find" hint="Describe it in a sentence or two, the way you'd brief a colleague.">
            <textarea value={f.description} onChange={(e) => setF({ ...f, description: e.target.value })}
              placeholder="The customer says the product is too expensive or asks for a discount." />
          </Field>
        )}
        <p className="muted small">Everyone subscribed gets a notification when this comes up in a new meeting. You're subscribed automatically.</p>
        {error && <p className="form-error" role="alert">{error}</p>}
      </form>
    </Modal>
  )
}

export function TrackersPage() {
  const { toast } = useApp()
  const list = useApi('/trackers', { poll: (d) => (d?.some((t) => t.pending) ? 4000 : 0) })
  const [editing, setEditing] = useState(null) // null | 'new' | tracker
  const [, run] = useAction(toast)
  const toggleSub = (t) => run(t.id, async () => {
    await (t.subscribed ? del(`/trackers/${t.id}/subscribe`) : post(`/trackers/${t.id}/subscribe`))
    list.setData((d) => d.map((x) => (x.id === t.id ? { ...x, subscribed: !t.subscribed } : x)))
  }, t.subscribed ? 'Unsubscribed' : 'Subscribed. You will be notified when it comes up.')
  const remove = (t) => {
    if (!confirm(`Delete the tracker “${t.name}”? Its matches are removed too.`)) return
    run(t.id, async () => { await del(`/trackers/${t.id}`); list.reload() }, 'Tracker deleted')
  }
  return (
    <main className="page">
      <PageHead title="Trackers" sub="Follow topics across every meeting you can see, like competitors, pricing or churn risk."
        actions={<button className="primary" onClick={() => setEditing('new')}>New tracker</button>} />
      <ErrorNote error={list.error} retry={list.reload} />
      {list.loading && !list.data && <Loading />}
      {list.data && !list.data.length && (
        <Empty title="No trackers yet" action={<button className="primary" onClick={() => setEditing('new')}>Create your first tracker</button>}>
          A tracker finds moments across all your team's calls, by exact keywords or by meaning.
        </Empty>
      )}
      <div className="in-list">
        {list.data?.map((t) => (
          <div key={t.id} className="in-item">
            <div className="in-item-main">
              <h3><a href={`#/trackers/${t.id}`}>{t.name}</a> <span className="tag">{t.kind === 'ai' ? 'AI' : 'Keywords'}</span></h3>
              {t.kind === 'keyword'
                ? <div className="in-kw">{t.terms.keywords.map((k) => <span key={k} className="tag quiet">{k}</span>)}</div>
                : <p className="in-item-meta">{t.terms.description}</p>}
              <p className="in-item-meta">
                {t.pending ? <Spinner label="Scanning past meetings" /> : (
                  <><span className="in-count">{t.hits_30d}</span> {t.hits_30d === 1 ? 'mention' : 'mentions'} in <span className="in-count">{t.meetings_30d}</span> {t.meetings_30d === 1 ? 'meeting' : 'meetings'} in the last 30 days · made by {t.owner_name}</>
                )}
              </p>
            </div>
            <div className="in-item-side">
              <button className={t.subscribed ? 'secondary small-btn' : 'primary small-btn'} onClick={() => toggleSub(t)} aria-pressed={t.subscribed}>
                {t.subscribed ? 'Subscribed' : 'Subscribe'}
              </button>
              {t.can_edit && (
                <Menu label={`More actions for ${t.name}`} items={[
                  { label: 'Edit', onClick: () => setEditing(t) },
                  { label: 'Delete', danger: true, onClick: () => remove(t) },
                ]} />
              )}
            </div>
          </div>
        ))}
      </div>
      {editing && <TrackerModal tracker={editing === 'new' ? null : editing} onClose={() => setEditing(null)} onSaved={list.reload} />}
    </main>
  )
}

function weekStart(iso) {
  const d = new Date(iso)
  d.setHours(0, 0, 0, 0)
  d.setDate(d.getDate() - ((d.getDay() + 6) % 7))
  return d.getTime()
}

function WeeklyChart({ hits, days }) {
  const weeks = Math.max(2, Math.ceil(days / 7))
  const now = weekStart(new Date().toISOString())
  const buckets = Array.from({ length: weeks }, (_, i) => ({ start: now - (weeks - 1 - i) * 7 * 86400000, n: 0 }))
  hits.forEach((h) => {
    const w = weekStart(h.date)
    const b = buckets.find((x) => x.start === w)
    if (b) b.n += 1
  })
  const max = Math.max(1, ...buckets.map((b) => b.n))
  return (
    <div className="in-chart" role="img" aria-label={`Mentions per week: ${buckets.map((b) => `week of ${fmtDay(new Date(b.start).toISOString())}, ${b.n}`).join('; ')}`}>
      {buckets.map((b) => (
        <span key={b.start} className={b.n ? 'in-bar' : 'in-bar zero'} style={{ height: `${(b.n / max) * 100}%` }}
          title={`Week of ${fmtDay(new Date(b.start).toISOString())}: ${b.n}`} />
      ))}
    </div>
  )
}

export function TrackerPage({ id }) {
  const [days, setDays] = useState(90)
  const trackers = useApi('/trackers', { poll: (d) => (d?.find((t) => t.id === id)?.pending ? 4000 : 0) })
  const hits = useApi(`/trackers/${id}/hits${qs({ days })}`)
  const tracker = trackers.data?.find((t) => t.id === id)
  const pendingRef = useRef(tracker?.pending)
  useEffect(() => {
    // When the backfill finishes, load the new matches.
    if (pendingRef.current && tracker && !tracker.pending) hits.reload()
    pendingRef.current = tracker?.pending
  }, [tracker?.pending]) // eslint-disable-line react-hooks/exhaustive-deps
  const groups = useMemo(() => {
    const g = new Map()
    for (const h of hits.data || []) {
      if (!g.has(h.meeting_id)) g.set(h.meeting_id, { id: h.meeting_id, title: h.title, date: h.date, hits: [] })
      g.get(h.meeting_id).hits.push(h)
    }
    return [...g.values()]
  }, [hits.data])
  if (trackers.loading && !trackers.data) return <main className="page"><Loading /></main>
  if (trackers.data && !tracker) {
    return <main className="page"><Empty title="That tracker doesn't exist" action={<a href="#/trackers">Back to trackers</a>}>It may have been deleted.</Empty></main>
  }
  return (
    <main className="page">
      <a className="back" href="#/trackers">Trackers</a>
      <PageHead title={tracker?.name || 'Tracker'} sub={tracker && (tracker.kind === 'ai' ? tracker.terms.description : `Keywords: ${tracker.terms.keywords.join(', ')}`)} />
      <div className="in-filters">
        <Seg label="Time range" value={days} onChange={setDays} options={[[30, '30 days'], [90, '90 days'], [365, '1 year']]} />
        {tracker?.pending && <Spinner label="Scanning past meetings" />}
      </div>
      <ErrorNote error={hits.error} retry={hits.reload} />
      {hits.loading && !hits.data && <Loading />}
      {hits.data && (
        <>
          <WeeklyChart hits={hits.data} days={days} />
          <p className="in-note">{hits.data.length} {hits.data.length === 1 ? 'mention' : 'mentions'} in {groups.length} {groups.length === 1 ? 'meeting' : 'meetings'}.</p>
          {!groups.length && <Empty title="No mentions in this period">Try a longer time range, or check back after new meetings are processed.</Empty>}
          {groups.map((g) => (
            <section key={g.id} className="in-hit-group">
              <h3><a href={`#/meeting/${g.id}`}>{g.title}</a></h3>
              <p className="in-item-meta">{fmtDay(g.date)}</p>
              {g.hits.map((h, i) => (
                <div key={i} className="in-hit">
                  <a className="clock" href={`#/meeting/${g.id}?t=${Math.floor(h.t)}`} aria-label={`Play from ${fmtClock(h.t)}`}>{fmtClock(h.t)}</a>
                  <q>{h.quote}</q>
                </div>
              ))}
            </section>
          ))}
        </>
      )}
    </main>
  )
}

/* ---------- coaching ---------- */
const val = (v, fmt = (x) => x) => (v === null || v === undefined ? <span className="in-dim">–</span> : fmt(v))

function TalkMetrics() {
  const { isAdmin, isLead } = useApp()
  const [days, setDays] = useState(30)
  const [team, setTeam] = useState('')
  const teams = useApi(isAdmin || isLead ? '/org/teams' : null)
  const data = useApi(`/coaching${qs({ days, team_id: team })}`)
  return (
    <>
      <div className="in-filters">
        <Seg label="Time range" value={days} onChange={setDays} options={[[7, '7 days'], [30, '30 days'], [90, '90 days']]} />
        {(isAdmin || isLead) && teams.data?.length > 0 && (
          <select value={team} onChange={(e) => setTeam(e.target.value)} aria-label="Team">
            <option value="">All people I coach</option>
            {teams.data.map((t) => <option key={t.id} value={t.id}>{t.name}</option>)}
          </select>
        )}
      </div>
      <p className="in-note">
        Metrics count only meetings where a speaker was linked to that teammate on the meeting page.
        On sales discovery calls, the rep usually talks about 40 to 60 percent of the time.
        {!isAdmin && !isLead && ' You see your own numbers; team leads and admins see their teams.'}
      </p>
      <ErrorNote error={data.error} retry={data.reload} />
      {data.loading && !data.data && <Loading />}
      {data.data && (
        <div className="in-table-wrap">
          <table className="in-table">
            <thead>
              <tr>
                <th>Person</th><th className="num">Meetings</th><th className="num">Talk %</th><th className="num">Words per minute</th>
                <th className="num">Questions per call</th><th className="num">Longest monologue</th><th className="num">Monologues</th>
              </tr>
            </thead>
            <tbody>
              {data.data.people.map((p) => (
                <tr key={p.user.id}>
                  <td><span className="in-person"><Avatar name={p.user.name} id={p.user.id} size={24} />{p.user.name}</span></td>
                  <td className="num">{p.meetings}</td>
                  <td className="num">{val(p.talk_pct, (v) => `${Math.round(v)}%`)}</td>
                  <td className="num">{val(p.wpm, Math.round)}</td>
                  <td className="num">{val(p.questions_per_call)}</td>
                  <td className="num">{val(p.longest_monologue, fmtClock)}</td>
                  <td className="num">{p.meetings ? p.monologues : val(null)}</td>
                </tr>
              ))}
              {!data.data.people.length && <tr><td colSpan={7} className="in-dim">No one to show.</td></tr>}
            </tbody>
          </table>
        </div>
      )}
    </>
  )
}

